private boolean stopped = false;      // set from the owner thread

public void run() {
    while (!stopped) {
        try {
            poll();
            Thread.sleep(500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return;
        }
    }
}

Thread worker = new Thread(() -> {
    while (!Thread.currentThread().isInterrupted()) {
        compute();                    // CPU only, no blocking calls
    }
    System.out.println("stopped");
});
worker.start();
worker.interrupt();
worker.join();
System.out.println("owner continues");
